ProjectALife.DialogueShards["scenes_any_31"] = {
{"s8_crime_sour_mash_apology_233","any",2,"reg=crime|mood=sad",{1,"Last thing I told Daddy was his mash went sour and he was too proud to admit it",2,"Was it sour?",1,"Sour as a pickle, and he was too proud - both",2,"Well",1,"I'd drink a jar of it right now, sour and all"}},
{"s8_crime_clinic_cases_234","any",3,"reg=crime|day=14,3650|mood=calm",{1,"Doctor at the Rosewood clinic wants a case of the high proof",2,"What's a doctor want with it?",3,"Cleaning wounds - cleaning tools, they ran out of rubbing alcohol the second week",1,"What's he trading?",3,"Stitches for anybody in the family, and he don't ask how you got cut",2,"That's worth two cases"}},
{"s8_crime_seed_jar_235","any",2,"reg=crime|day=60,3650|mood=warm",{1,"Save every seed off the best plant - jar 'em - write the year on the lid",2,"You planning on next year?",1,"Planning on next year's the only reason I get up",2,"Write it big, then"}},
{"s8_crime_lester_tv_236","any",2,"reg=crime|day=4,3650|mood=funny",{1,"That first Friday, Lester came in to buy his TV back - wanted to watch the news",2,"What'd the news say?",1,"Man in a suit said stay calm - Lester paid in quarters",2,"He get it home?",1,"Got it home, watched it till the static, brought it back Tuesday and asked what I'd give him"}},
{"s8_crime_lords_day_237","any",3,"reg=crime|mood=funny",{1,"Mamaw never allowed the still fired on the Lord's day",2,"Mamaw's been gone four years",1,"I was at the funeral, Dale",3,"So are we firing it or not?",1,"We're firing it, but nobody tastes a drop till Monday"}},
{"s8_crime_first_quart_238","any",2,"reg=crime|mood=funny",{1,"Don't drink off the first quart of the run - that's the part that'll blind you, swear to God",2,"Tackett boys drink the first quart",1,"Tackett boys can't find their own front door",2,"I always figured that was the liquor",1,"Now you know which liquor"}},
{"s8_crime_room_of_stuff_239","any",2,"reg=crime|day=7,3650|mood=sad|world=vehicle",{1,"I'm taking the truck to Brandenburg, Daddy, there's people there",2,"There's people here, there's the shop",1,"The shop's a room full of stuff nobody's ever gonna buy",2,"It's my room full of stuff",1,"Then you stay with it, I'll send word with the club boys when they come through"}},
{"s8_crime_amoxicillin_ounce_240","any",3,"reg=crime|day=20,3650|mood=calm",{1,"Woman at the church clinic says an ounce gets us a bottle of amoxicillin",2,"Church clinic's buying weed?",1,"For the ones who can't keep food down, the nurse there knows what she's doing",3,"Church people buying off us - Mama'd laugh herself sick",2,"Get two bottles"}},
{"s8_crime_uncle_roy_porch_241","any",2,"reg=crime|hour=18,2|mood=grim|world=building",{1,"Uncle Roy's sat on the porch with the rifle since supper",2,"He do that in the war?",1,"Don't know, he never talked about the war - never talked about nothing",2,"Take him a jar",1,"Took him one, he poured it out on the steps and said not tonight"}},
{"s8_crime_merle_rope_chain_242","any",3,"reg=crime|day=5,3650|mood=funny",{1,"Merle always said when he died, sell everything in the shop and throw a party",2,"Who's buying?",3,"Nobody, so we're throwing a party with everything in the shop",1,"I'm wearing his gold rope chain",2,"It's hideous",1,"He'd have wanted it seen"}},
{"s8_crime_barn_roof_243","any",2,"reg=crime|hour=19,5|mood=calm|world=vehicle,building,fog",{1,"Could we fire a still after dark without being noticed?",2,"I wouldn't count on it",1,"What if we found a barn?",2,"What if the roof's half gone? Walls aren't a promise of cover",1,"Then I keep thinking. Hell, can't even make a plan without an argument"}},
{"s8_crime_title_paid_244","any",2,"reg=crime|day=5,3650|mood=funny|world=vehicle",{1,"Got the title to Bobby Ray's truck in the safe - he owes eight hundred",2,"So go get the truck",1,"It's in his barn, so's Bobby Ray",2,"Up and around?",1,"Up and around - real grabby, I'm calling it paid in full"}},
{"s8_crime_porch_row_245","any",2,"reg=crime|day=30,3650|hour=4,11|mood=funny|world=building",{1,"First rule of growing, never on your own land - they'll take the farm",2,"Who's taking it now?",1,"That's what I said, planted a row right up against the front porch this morning",2,"Right against the porch?",1,"Where I can see it from the rocker, I earned a rocker"}},
{"s8_crime_cabinet_orders_246","any",2,"reg=crime|day=5,3650|mood=sad|world=building",{1,"Opal's still got the orders taped up on the kitchen cabinet",2,"Any we can fill?",1,"Pint of peach for Leroy Sims, quart for the Dawson boy's wedding - two pints for Mr. Haney, on credit",2,"Take 'em down?",1,"She won't let me, says they might still come by"}},
{"s8_crime_kid_revolver_247","any",3,"reg=crime|day=5,3650|mood=warm|world=door",{1,"I remember a kid wanting to trade his daddy's revolver for soup",2,"Merle's rule, never buy off a kid",3,"That rule was for kids stealing. This kid said his daddy was buried in the yard",1,"So what did you do?",2,"Tried to get him help. A hungry kid shouldn't have to bargain with a gun"}},
{"s8_crime_hymnal_code_248","any",2,"reg=crime|mood=funny|world=water",{1,"On the CB, a jar's a Bible, a case is a hymnal",2,"Why church words?",1,"Revenue men never listened close to Bible talk",2,"What's a raid?",1,"Revival, you hear revival, you dump everything in the creek and go fishing"}},
{"s8_crime_calendar_safe_249","any",3,"reg=crime|day=5,3650|mood=funny",{1,"What's the combination on the big safe?",2,"Merle had it",3,"Merle wrote it on the calendar, on the day he bought the safe",1,"What day?",3,"Don't know, calendar's at his house",2,"His house is the one with a yard full of them",1,"Then we drill - Drill's loud - get the bats"}},
{"s8_crime_thumper_mutter_250","any",1,"reg=crime|hour=19,5|mood=calm|world=water",{1,"Low and slow - don't let her puke - hear that thumper? That's her heartbeat",1,"Daddy stood right here, his daddy stood right here - same rock - same creek",1,"Whole county died, and the creek's still cold, that's something, I reckon"}},
{"s8_crime_trim_party_251","any",3,"reg=crime|day=60,160|hour=19,2|mood=warm",{1,"Trim party, scissors, a bedsheet on the floor, and nobody talks above a whisper",2,"Used to have the radio going for these",3,"Hum, then - real low",1,"Nobody hums, your humming sounds like a hurt calf",3,"Then I'll hum in my head",2,"Somehow I can still hear it"}},
{"s8_crime_doris_pears_252","any",2,"reg=crime|day=30,3650|hour=4,11|mood=warm",{1,"Doris Whitt walked in this morning - alive, skinny as a rail",2,"For the ring?",1,"Asked what she owed, I told her the interest was waived on account of the end of the world",2,"She laugh?",1,"Paid me a can of pears anyhow, said she don't take charity from a pawnbroker"}},
{"s8_crime_revenue_man_253","any",3,"reg=crime|day=5,3650|mood=calm",{1,"A man once came to our gate saying he was a federal agent. Chased Papaw eleven years",2,"He ever catch him?",1,"Once - Papaw was out on bond by supper",3,"What was he after?",1,"A drink and somewhere to sleep. Had a bad cough and a good pistol",2,"Papaw would've wanted him to taste how good the liquor got. I mostly wanted to know if he was telling the truth"}},
{"s8_crime_triple_beam_254","any",2,"reg=crime|day=14,3650|mood=calm|world=building",{1,"What's the triple beam scale doing in the kitchen?",2,"Weighing rice, eight ounces a person a day",1,"That scale's weighed a lot more trouble than rice",2,"Rice is trouble now - ask anybody who comes up short"}},
{"s8_crime_false_floor_255","any",3,"reg=crime|day=7,3650|mood=calm|world=vehicle",{1,"Papaw's old truck still has the false floor in the bed - holds forty jars",2,"What are we hiding in it?",3,"Everything we don't want the West Point boys taking - shells - pills, the good knife",1,"Thirty years that truck hid liquor from the law, now it hides bandages from thieves - truck's come up in the world"}},
{"s8_crime_slippers_porch_256","any",3,"reg=crime|day=5,3650|mood=grim|world=building",{1,"Next house is the Whitlocks', he pawned his shotgun with us every hunting season",2,"So you know the house",1,"I know he keeps shells in the freezer, I know his wife makes him wear slippers inside",3,"Anybody home?",1,"Both pair of slippers are on the porch - let's go"}},
{"s8_crime_see_through_time_257","any",2,"reg=crime|day=10,3650|mood=funny",{1,"Club president wanted a taste before he bought, took a big swallow",2,"Of the fuel batch?",1,"The very same",2,"He alright?",1,"Says he can see through time now, bought four cases"}},
{"s8_crime_squirrel_hunter_258","any",2,"reg=crime|mood=sad",{1,"Carol never knew about the patch - twenty years, thought I went squirrel hunting a lot",2,"She believed that?",1,"She told me once I was the worst squirrel hunter in Kentucky - never brought a one home",2,"She knew",1,"Yeah, I figure she knew"}},
{"s8_crime_cider_ribbons_259","any",2,"reg=crime|mood=funny",{1,"Aunt Opal won the blue ribbon for apple cider at the county fair nine years running",2,"Cider",1,"Same three judges every year, took a sip, gave her a ribbon and a long hug",2,"Where are the ribbons now?",1,"Nailed up over the still, she says the still earned 'em"}},
{"s8_crime_basement_twenties_260","any",2,"reg=crime|day=7,3650|mood=funny",{1,"Spent two years learning to print twenties in Shorty's basement",2,"Good ones?",1,"Best in Kentucky, nobody could tell",2,"And now nobody takes the real ones either",1,"So mine are finally worth exactly what theirs are"}},
{"s8_crime_north_rows_family_261","any",3,"reg=crime|day=20,3650|mood=angry",{1,"Somebody's camped in the bean rows, tent pitched right between 'em",2,"Raiders?",3,"Family, man, woman, two little ones, they're eating the beans",1,"Them's my beans",2,"And them's somebody's kids",1,"Then tell 'em pick from the east rows, the north rows ain't ripe yet"}},
{"s8_crime_mail_slot_262","any",2,"reg=crime|day=3,3650|mood=funny|world=window",{1,"Tammy put down four of 'em through the mail slot with a steak knife on a broom handle",2,"Through the mail slot?",1,"One at a time, said it's just like working the drive-through window at the bank",2,"She did work the drive-through",1,"Eleven years, says a dead one's got better manners than a Friday customer"}},
{"s8_crime_last_weld_263","any",2,"reg=crime|mood=sad",{1,"Daddy was halfway through building the new still when it happened - boiler welded, no cap",2,"You finish it?",1,"Finished it last night, most of it",2,"Most?",1,"Left one seam on the back undone, that one's his"}},
{"s8_crime_burkhart_copper_264","any",3,"reg=crime|day=5,3650|mood=funny",{1,"Deputy Burkhart's at the door, the one who busted our still in eighty-eight",2,"Come to arrest us again?",1,"A job, says he knows every hiding spot in the county, since he found most of 'em",3,"Hire him",2,"He hauled off Daddy's copper",3,"Then his first job is finding us new copper"}},
{"s8_crime_rain_barn_265","any",2,"reg=crime|day=20,120|mood=warm|world=building",{1,"Hear that on the barn roof?",2,"Finally, three weeks of nothing but sun",1,"Beans'll come back - Corn'll come back",2,"Something in this county gets to come back that ain't hungry for us"}},
{"s8_crime_sickle_mutter_266","any",1,"reg=crime|hour=20,5|mood=fear",{1,"Something's in the rows, something walking the rows",1,"Plants don't care, plants just stand there getting taller, must be nice",1,"Come on out, then, I got a sickle and I ain't got nowhere else to be"}},
{"s8_crime_raise_peaches_267","any",2,"reg=crime|day=10,3650|mood=funny",{1,"Tammy wants a raise",2,"She makes four twenty-five an hour",1,"She wants it in peaches",2,"How many peaches is four twenty-five?",1,"She says all of 'em"}},
{"s8_crime_squirrel_grace_268","any",4,"reg=crime|hour=17,21|mood=warm",{1,"Bow your heads - Lord, thank you for the squirrel, the beans, and the cornbread",2,"And the jar",1,"And the jar, and keep the Tacketts on their side of the ridge",3,"And Uncle Roy",1,"And Roy, wherever he got off to - amen",4,"Pass the squirrel"}},
{"s8_crime_fur_coat_269","any",2,"reg=crime|day=3,70|mood=funny",{1,"Man walked in wearing a fur coat, hundred degrees out",2,"What for?",1,"Only way to carry it, wanted to trade it for a pistol",2,"You take it?",1,"Took it, first thing I've bought in months I'll be glad of come January"}},
{"s8_crime_dickie_flag_270","any",3,"reg=crime|day=5,3650|mood=grim|world=road",{1,"Dickie Farris is coming up the road with a white flag - the one who testified on Uncle Roy",2,"Roy did seven years on account of Dickie",3,"Dickie's got a busted leg and nothing on him but that flag",1,"What are we doing about him?",2,"Let him go by. Don't help him, don't lay a hand on him. We never saw him",3,"So we watch him limp past",2,"Yeah. And he gets to keep walking. That's us being merciful"}},
{"s8_crime_october_wedding_271","any",2,"reg=crime|day=14,3650|mood=warm",{1,"Couple in Riverside's getting married Saturday, want two quarts",2,"Getting married - now",1,"Said they were waiting on October, said October ain't promised",2,"Give 'em three, on the house"}},
{"s8_gangcrime_office_hours_272","any",3,"reg=gang,crime|day=3,3650|mood=grim|world=door",{1,"Doctor's office on Main Street, same doctor wrote half the pills this county ever bought",2,"Door's chained from the inside",3,"So the doctor's inside",1,"He's in there, you can hear him pacing the waiting room",2,"Still keeping office hours"}},
{"s8_gangcrime_johnboat_273","any",3,"reg=gang,crime|day=3,120|hour=21,5|mood=fear|world=water",{1,"Johnboat, no motor, oarlocks wrapped in rags, across the river after midnight",2,"Army's got searchlights on the Indiana bank",3,"Tammy's cousin tried it Tuesday",1,"And?",3,"Light found him halfway, boat drifted back empty next morning, turning in circles",2,"So not tonight"}},
{"s8_clubcrime_labor_day_tab_274","any",2,"reg=club,crime|day=7,3650|mood=funny",{1,"Your club still owes my family nine hundred dollars from the Labor Day party",2,"That party was last September, and half the men who drank it are dead",1,"Other half ain't",2,"Fine, we'll settle up in gas - two gallons",1,"Nine hundred dollars is not two gallons",2,"It is this week"}},
{"s8_crime_no_eyebrows_275","any",3,"reg=crime|mood=funny",{1,"What happened to your eyebrows?",2,"Propane leak on the burner",3,"Went up so loud it pulled half the holler down on us",2,"And I put down every one of 'em with no eyebrows",3,"Only thing scarier than the dead is Dale with no eyebrows"}},
{"s8_crime_still_criminals_276","any",2,"reg=crime|day=14,3650|mood=funny",{1,"Are we still criminals if there ain't no law?",2,"Law's just a bunch of people agreeing on something",1,"Nobody's agreeing on nothing",2,"Then we're farmers, real proud farmers"}},
{"s8_crime_revolver_boy_back_277","any",2,"reg=crime|day=20,3650|mood=warm",{1,"That boy with his daddy's revolver came back",2,"Wanting soup again?",1,"Brought us two cans, said the revolver worked just like we showed him",2,"He alright?",1,"Got his little sister with him now, he's alright enough"}},
{"s8_crime_tarp_habit_278","any",2,"reg=crime|day=7,3650|mood=funny",{1,"You still dive under the tarp every time a helicopter comes over",2,"Habit",1,"It's the Army, they don't care about the plants",2,"That's what they want you to think"}},
{"s8_crime_blue_flame_279","any",2,"reg=crime|hour=19,4|mood=calm",{1,"Light a spoonful - watch",2,"It's blue, you can barely see it",1,"Blue and clean is good, yellow means your cousin cut it with something",2,"Which cousin?",1,"All of 'em, one time or another"}},
{"s8_crime_open_sign_mutter_280","any",1,"reg=crime|day=10,3650|mood=sad|world=door",{1,"Open at nine, close at six - sign stays flipped to open - Merle's rule",1,"Nobody's come through that door in a week that wasn't dead or desperate",1,"Sign stays on open, he'd skin me alive if it didn't"}},
{"s8_crime_tackett_burying_281","any",2,"reg=crime|day=7,3650|mood=sad",{1,"Old man Tackett's dead, his boy walked over the ridge with his hat in his hands to tell us",2,"Fifty years that man shot at us",1,"Mostly missed",2,"Mostly",1,"I'm going to the burying, somebody's gotta make sure he stays down"}},
{"s8_crime_tickets_cage_282","any",3,"reg=crime|day=5,3650|mood=angry",{1,"City boys from the motel want the guns out of the shop",2,"Them guns are on tickets, they belong to people",3,"People who ain't coming",2,"Then they belong to me till the tickets run out",1,"When do the tickets run out?",2,"When I say - lock the cage"}},
{"s8_crime_hearse_lily_283","any",2,"reg=crime|mood=funny",{1,"My granddaddy ran liquor to Louisville in nineteen twenty-nine, in a hearse",2,"A hearse?",1,"Nobody stops a hearse, he'd lay a lily on the dash and do thirty-five the whole way",2,"Funeral home in Muldraugh's got a hearse sitting out back",1,"Nobody'd stop a hearse now, either - different reasons"}},
{"s8_crime_sign_closed_284","any",2,"reg=crime|day=14,3650|mood=sad|world=building,road",{1,"Lost Merle, lost the Newsomes next door - lost my boy Wade on the Rosewood road",2,"Lord, all three",1,"If you get back there before me, tell the others I made it"}},
{"s8_crime_tomatoes_285","any",2,"reg=crime|day=30,3650|mood=funny",{1,"My niece asked what the tall plants are",2,"And you said?",1,"Tomatoes",2,"She buy it?",1,"She asks every morning when the tomatoes come in, I say any day now, that was a month ago"}},
{"s8_crime_cowbell_286","any",3,"reg=crime|mood=calm",{1,"Old signal was one shot for a revenue man, two for the sheriff",2,"Can't shoot now, pulls 'em in",3,"Cowbell, one ring, stranger - two, dead ones - three, run",1,"Where'd you find a cowbell?",3,"On a cow"}},
{"s8_crimegang_batteries_word_287","any",2,"reg=crime,gang|day=7,3650|mood=calm",{1,"Motel crew wants to trade a case of batteries for the deer rifle",2,"Batteries are good - what's their word worth?",1,"Their boss walked the batteries over himself, no gun on him",2,"Then his word's worth a rifle"}},
{"s8_crime_dry_sign_288","any",2,"reg=crime|mood=funny",{1,"Sign coming into the county still says alcohol sales prohibited",2,"Only law left standing in Knox County",1,"And it's still the one nobody obeys"}},
{"s8_crime_granny_apron_289","any",3,"reg=crime|hour=17,21|mood=funny|world=building",{1,"Granny says no more guns at the supper table",2,"There's dead ones in the yard, Granny",3,"Then eat fast, guns on the porch",1,"You heard her",2,"She's got a pistol in her apron pocket",3,"I'm eighty-one, I'm the exception"}},
{"s8_crime_music_box_ticket_290","any",2,"reg=crime|mood=sad",{1,"Somebody pawned a music box in June, little dancer on top",2,"Does it play?",1,"Plays, I wind it when the shop gets too quiet",2,"Whose was it?",1,"Ticket says Amber Lynn Carter, age nine, her mama signed for her"}},
{"s8_crime_broad_daylight_mutter_291","any",1,"reg=crime|day=60,160|hour=9,17|mood=calm",{1,"Twenty years hiding in these rows, now I stand in the middle of 'em in broad daylight",1,"Nobody to catch me, nobody to sell to - nobody to brag to",1,"Grew it anyway - Junior'd cuss out loud at how tall it got"}},
{"s8_crime_keep_the_level_292","any",4,"reg=crime|day=5,3650|mood=warm|world=vehicle",{1,"Family's all here - vote - do the church bus people stay in the hay barn?",2,"The still's in the hay barn",3,"Move the still",4,"Move it? Took Papaw three weeks to get that thing level",1,"Them people got a baby that won't quit coughing",4,"Fine, move the still - I'm keeping the level"}},
{"s8_crime_army_boy_rifle_293","any",2,"reg=crime|day=5,3650|mood=grim|world=building,road",{1,"First customer after they shut the roads was an Army boy - still in uniform",2,"What'd he pay with?",1,"His rifle, said he didn't want to look at it for a while",2,"Then where'd he get off to?",1,"Drank half a jar on the porch and slept, woke up and walked back toward the wire"}},
{"s8_crime_favor_owed_294","any",3,"reg=crime|day=5,3650|mood=grim|world=water",{1,"Papaw always said a favor owed don't die with the man",2,"So who's owed?",3,"Wendell Tate pulled Papaw out of the river in sixty-eight - Papaw never paid it back",1,"Wendell's grandson is at the gate burning up with fever",2,"Then open the gate - we're paying"}},
{"s8_crime_opal_back_door_mutter_295","any",1,"reg=crime|day=7,3650|mood=sad|world=door",{1,"Pint of peach for Leroy, I'll set it by the back step, just in case",1,"Sheriff's pint on Friday - Deacon's jar, for his poor wife's memory",1,"Back door's always open, it was always open, it's the county that closed"}},
{"s8_gangcrime_socks_jars_296","any",3,"reg=gang,crime|day=7,3650|mood=calm|world=water,road",{1,"Route is the motel, the feed store, the creek ford, then the Tate farm - no main roads",2,"Who's carrying the jars?",3,"Whoever's quietest - glass clinks",1,"Wrap every jar in a sock",2,"We ain't got that many socks",3,"Then nobody's wearing socks tomorrow"}},
{"s8_crime_class_ring_297","any",2,"reg=crime|day=7,3650|mood=grim",{1,"Raider came in to trade a class ring - nineteen seventy-four - initials D.W.H",2,"So?",1,"Danny Hurt, sold him fishing lures every spring for twenty years",2,"You trade with him?",1,"Traded, kept the ring behind the counter, somebody ought to know where it ended up"}},
{"s8_crime_wendell_rows_298","any",2,"reg=crime|day=40,160|mood=grim",{1,"Wendell's up in the north rows",2,"Wendell's been dead a week",1,"I know, he's still up there walking the rows",2,"Want me to take care of it?",1,"Give him till harvest, he always did want to see it come in"}},
{"s8_crime_loud_sun_299","any",2,"reg=crime|hour=5,10|mood=funny|world=building",{1,"Why is the sun so loud?",2,"That's the rooster",1,"Shoot the rooster",2,"Rooster's the only one on this farm who got up on time"}},
{"s8_crime_fence_prices_mutter_300","any",1,"reg=crime|day=14,3650|mood=funny",{1,"Gold watch, fifteen hundred, diamond earrings, eight hundred - color TV with the remote, two hundred",1,"Can of beef stew, can't get it, box of shells, can't get it, dry socks, don't even ask",1,"Twenty years in this business, and I should've been in socks"}},
{"s9_c01_mono_parking_quarter_001","any",1,"reg=family|tmp=fresh,seasoned|sex=m|hour=18,23|mood=sad|world=building",{1,"Okay, Linda, I'm gonna get through it this time, so just let me talk",1,"I keep remembering Tessa losing a tooth Tuesday. Hid it under a couch cushion because she couldn't find her pillow",1,"I put a quarter there, the kind you kept for parking meters in Elizabethtown. Keep going back to that one small thing I could do",1,"That's the memory I wanted to tell you. I wish I had news, Linda"}},
{"s9_c01_mono_left_at_the_fish_002","any",1,"reg=civilian|tmp=seasoned|hour=7,18|mood=funny|world=building,road",{1,"Mailbox shaped like a largemouth bass, that's the Brumley road, means Ekron's still four miles",1,"Used to give everybody directions by this fish - go past the church, left at the fish, whole county knew the fish",1,"Somebody shot it, right through the mouth - now what am I supposed to tell people?",1,"Nobody to tell, left at the fish, then"}},
{"s9_c01_mono_ugly_tomatoes_003","any",1,"reg=civilian,family|tmp=fresh|sex=f|day=3,30|hour=20,2|mood=sad|world=rain",{1,"Lord, I quit asking about the Army on Tuesday, I figure You heard enough about the Army",1,"This one's smaller - keep the rain off till I get the tarp over the woodpile - you can do that one",1,"And Donna, if You've got Donna, tell her I watered her tomatoes like I promised - even the ugly ones - amen"}},
{"s9_c01_mono_open_house_004","any",1,"reg=civilian|tmp=seasoned|mood=funny|world=door,window,building",{1,"Three bedroom, one bath, original windows, mostly broken, but original",1,"Motivated sellers - real motivated, left the coffee maker on and the door wide open",1,"Open house every day this week, nobody's come to look but the neighbors, and the neighbors bite"}},
{"s9_c01_mono_cooler_draw_005","any",1,"reg=family|role=family_elder|hour=11,17|mood=calm",{1,"Knees are talking to me today, both of 'em, and neither one's saying anything nice",1,"Sat down on this cooler to rest a minute, that was about an hour ago, I'd guess",1,"Sun moved - I didn't, let's call it a draw"}},
{"s9_c01_mono_gutters_first_006","any",1,"reg=civilian|tmp=fresh|day=2,25|mood=sad|world=vehicle",{1,"When I find Dale, I'll say you were right about the gutters - start there, he'll like starting there",1,"Then I'll say I shouldn't have sold Daddy's truck without asking him - that's the real one",1,"Gutters first, though, you don't walk up on Dale with the truck"}},
{"s9_c01_mono_overpass_letters_007","any",1,"reg=family|role=family_youth|day=2,20|mood=funny",{1,"Writing it on the overpass at Muldraugh, big as I can reach - KAYLA AND BEN PARRISH, GONE TO BRANDENBURG",1,"Spray can's about out - Brandenburg's got too many letters in it",1,"Should've picked Ekron - Ekron's short"}},
{"s9_c01_mono_bluegill_grief_008","any",1,"reg=civilian|role=civilian_loner|hour=5,9|mood=funny",{1,"Cork's been sitting still an hour, the fish don't know the world ended, and they still won't bite",1,"Or maybe they do know, maybe this is how a bluegill grieves",1,"Come on, then, come grieve on my hook"}},
{"s9_c01_mono_whistle_breathing_009","any",1,"reg=family|tmp=fresh|sex=f|hour=22,4|mood=fear",{1,"One, two, three, three of 'em breathing - okay",1,"Cody breathes like his daddy did, with that little whistle on the way out - I could find him in a dark field by it",1,"Everybody's breathing - go to sleep, Jen - lie down and go to sleep"}},
{"s9_c01_mono_delores_010","any",1,"reg=civilian|tmp=fresh|sex=m|day=1,8|mood=fear",{1,"Come on, Delores, you started in the ice storm of eighty-nine - you started when the transmission man swore you wouldn't",1,"I'll never call you ugly again, I'll wash you by hand - I'll buy you real floor mats",1,"Nothing - okay, okay, we walk - I'm taking the dice off your mirror, though"}},
{"s9_c01_mono_bean_field_011","any",1,"reg=family|role=family_elder|sex=f|day=5,90|mood=grim",{1,"Walter, I shot one today, came across the bean field in his church clothes, carrying one shoe",1,"Used your deer rifle, took me two tries - you'd have fussed at me about my breathing",1,"I'm not sorry about it, I just wanted you to hear it from me first"}},
{"s9_c01_mono_feet_no_vote_012","any",1,"reg=civilian|tmp=seasoned|day=14,120|hour=4,9|mood=calm|world=water",{1,"Riverside, burned - Rosewood, crawling - March Ridge, quiet, and I didn't care for the quiet",1,"Brandenburg next, my feet want the river, they been talking about the river since sunup",1,"Feet don't get a vote, feet never did"}},
{"s9_c01_mono_find_smooth_013","any",1,"reg=family,civilian|role=family_youth,civilian_woman,civilian_man|mood=funny",{1,"Dear diary, today I didn't die - big day, real exciting stuff",1,"Also found a whole jar of peanut butter, crunchy, which is wrong, but I've decided to forgive it",1,"Goals for tomorrow - don't die - find smooth"}},
{"s9_c01_mono_lead_with_not_bit_014","any",1,"reg=civilian|tmp=fresh|sex=m|day=2,30|mood=fear|world=vehicle",{1,"Hi - I'm Doug, I'm not bit - I can fix a small engine, and I don't eat much",1,"No, lead with not bit - nobody cares about any engine till they know you're not bit",1,"I'm not bit - I'm Doug, I eat a normal amount - okay, that's the speech"}},
{"s9_c01_mono_leave_one_on_015","any",1,"reg=family|tmp=fresh,seasoned|sex=m|hour=20,5|mood=sad",{1,"Lord, it's Randy Skaggs, I'm Baptist, so I don't have the fancy words - I just talk",1,"Look after Shelby for me - she's four, she's scared of the dark, so if it's dark up there, leave something on",1,"That's all, that's the prayer"}},
{"s9_c01_mono_awning_016","any",1,"reg=civilian|tmp=seasoned|hour=12,17|mood=funny",{1,"If I see the dead lined up in the shade, I'll figure they're waiting on a ride",1,"I'd be the fool standing in the sun, waiting right along with 'em",1,"'Scoot over, fellas' - no, I'd better not"}},
{"s9_c01_mono_zipper_017","any",1,"reg=family,civilian|tmp=seasoned|sex=f|day=20,150|hour=4,11|mood=sad",{1,"Didn't cry at the grave, didn't cry when I painted his name on the board",1,"Zipper stuck on my jacket this morning - Mike always did that zipper, my fingers are no good at it",1,"Stood out in the yard ten minutes bawling over a zipper - ten whole minutes"}},
{"s9_c01_mono_owl_dog_other_018","any",1,"reg=civilian,family|tmp=fresh|hour=23,4|mood=fear",{1,"That's an owl - Owls are fine",1,"That's a dog, way off, dogs are mostly fine",1,"That one I don't know, I'm gonna go right on not knowing it"}},
{"s9_c01_mono_stall_twelve_019","any",1,"reg=family|role=family_youth|day=1,30|mood=fear|world=vehicle",{1,"Clutch in - brake - first gear - clutch in - brake - first",1,"Stalled it again - that's twelve, every one of 'em in the holler heard number twelve",1,"Truck, you and me gotta be friends by dark"}},
{"s9_c01_mono_lazy_mans_grave_020","any",1,"reg=civilian|tmp=seasoned|mood=grim",{1,"Two feet is what I got in me, ground's nothing but rock under here",1,"Sorry, Mr. Lindsey, you'd have said two feet is a lazy man's grave",1,"You'd have been right, you were right about most anything to do with a shovel"}},
{"s9_c01_mono_mama_bear_021","any",1,"reg=family|sex=f|hour=20,1|mood=sad",{1,"Breaker one-nine, this is Mama Bear looking for Little Bear - come on back",1,"Jason, if you're out there, I know you hate that handle - I'll quit using it if you just answer me",1,"Mama Bear standing by - Mama Bear's always standing by"}},
{"s9_c01_mono_measure_once_022","any",1,"reg=family,civilian|sex=m|mood=funny",{1,"Measure twice, cut once, that's what Daddy always said",1,"Daddy never had one of 'em shoving on the other side of the board while he measured",1,"Measure once - cut fast, pray the board's long enough"}},
{"s9_c01_mono_church_step_023","any",1,"reg=civilian|tmp=fresh,seasoned|day=3,60|hour=6,10|mood=calm|world=door,window",{1,"Doors are open at First Christian, pews are all shoved against the windows",1,"Somebody stayed here a while, hymnals stacked up for a pillow, candle burned down to the saucer",1,"Guess I'll sit a minute, nobody's gonna ask me to put anything in the plate"}},
{"s9_c01_mono_bread_ties_024","any",1,"reg=family|tmp=seasoned|sex=f|day=15,120|mood=sad|world=vehicle",{1,"Found the junk drawer from the old house in the back of the truck - I don't remember packing a junk drawer",1,"Bread ties - birthday candles, the spare key to a car that burned in Riverside",1,"Carl's grocery list, eggs, foil, the good coffee - underlined the good coffee twice"}},
{"s9_c01_mono_county_line_025","any",1,"reg=civilian|role=civilian_loner|mood=grim|world=cars,fence",{1,"County line sign, leaving Knox County - thank you for visiting",1,"And a fence behind it, and two Army trucks behind the fence, and a whole lot of nobody visiting",1,"You're welcome, I'll show myself back in"}},
{"s9_c01_mono_leash_on_wrist_026","any",1,"reg=civilian|tmp=fresh|day=1,20|hour=8,19|mood=fear",{1,"Stay close, Peanut, stay close - no barking - good girl",1,"Leash is wrapped around my wrist twice, so if she runs, I run",1,"She's a better walker than me, doesn't look back once"}},
{"s9_c01_azaleas_001","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=2,40|mood=sad|world=road",{1,"You remember the Haddix boy? Delivered the paper on that bike with the bent fender?",2,"Threw it in my azaleas every morning for two years - every single morning, like he was aiming",1,"Found his canvas bag on the Rosewood road - still full - Friday's papers",2,"I'd give anything to go dig one out of the azaleas"}},
{"s9_c01_since_carter_002","any",2,"reg=family|mood=funny",{1,"Papaw slept through the whole thing last night, forty of 'em beating on the carport",2,"He takes his hearing aid out at night",1,"He says it's the best night's sleep he's had since the seventies"}},
{"s9_c01_rude_cigarette_003","any",2,"reg=civilian|tmp=fresh|day=1,25|mood=funny|world=window",{1,"Lady at the Ekron church let me finish her cigarette - she'd been coughing up something awful all night, hahaha!",2,"Tell me you didn't take it",1,"Didn't want to be rude, wonder if rude would've been the better call",2,"It's your turn on the window"}},
{"s9_c01_nine_sixteenths_004","any",2,"reg=family|tmp=fresh|day=2,30|mood=sad|world=building",{1,"Saturday was the day, training wheels off - he'd been asking since May",2,"You don't have to tell it",1,"Wrench is still on the porch step where I set it - nine-sixteenths, I haven't picked it up",2,"Then leave it there"}},
{"s9_c01_population_sign_005","any",2,"reg=civilian,family|tmp=seasoned|day=10,150|mood=funny",{1,"City limit sign coming into Muldraugh, somebody took a can of paint to the population",2,"What's it say now?",1,"Crossed the number out and wrote ask again later",2,"Most honest sign in Kentucky"}},
{"s9_c01_linty_sucker_006","any",2,"reg=family|mood=warm",{1,"Katie saved me half her sucker, wrapped it back up in the paper and everything",2,"She's been carrying that thing in her pocket since Sunday",1,"I know, lint all over it",2,"You eat it?",1,"Every bit, lint and all"}},
{"s9_c01_hoot_007","any",2,"reg=civilian|tmp=fresh,seasoned|day=2,60|mood=sad",{1,"The big fella in the overalls, the one that went back for the Tipton girl - anybody ever get his name?",2,"Said to call him Hoot, that's all I ever got out of him - Hoot",1,"Hoot, then, that's what goes on the cross",2,"Make the letters big, he was a big man"}},
{"s9_c01_smell_news_008","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=6,90|mood=funny|world=vehicle",{1,"Whole room smells like a gym bag somebody left in a hot car",2,"That's all of us, nobody's had a real bath since the ninth",1,"Good news is them things can't pick us out over each other",2,"Bad news is I can"}},
{"s9_c01_arithmetic_009","any",2,"reg=family|tmp=fresh,seasoned|mood=grim",{1,"If we have to run, Mason rides with you - Lila comes with me",2,"Why that way?",1,"You're faster, and Mason's heavier, that's all it is - it's arithmetic",2,"Say arithmetic again, I need to hear it's just arithmetic",1,"It's arithmetic, hon"}},
{"s9_c01_vernon_shelter_010","any",2,"reg=civilian,family|mood=funny",{1,"Uncle Vernon's fallout shelter, dug it in sixty-two, nobody's been down there since his funeral",2,"Anything good?",1,"Forty cans of powdered orange drink, a Geiger counter, and a Bible with a hole cut out for a flask",2,"Flask still in it?",1,"Empty - Vernon was ready for everything but Vernon"}},
{"s9_c01_no_cake_011","any",2,"reg=family|tmp=fresh|day=2,30|mood=sad",{1,"Josie wanted to know if the sick people still get birthdays",2,"Lord, what'd you tell her?",1,"Said sure they do, they just don't want any cake",2,"She take that?",1,"She asked could she have theirs"}},
{"s9_c01_socket_set_012","any",2,"reg=civilian|tmp=seasoned|day=20,150|mood=calm|world=fence",{1,"Beelers are trading eggs out at the Echo Creek bridge - a dozen for a box of twenty-twos",2,"That's steep",1,"Chickens are steep now, you try keeping a hen alive with them things walking the fence",2,"Offer half a box and I'll throw in the socket set",1,"Nobody wants a socket set, nobody's fixing anything",2,"They will next spring - tell 'em I said so"}},
{"s9_c01_quilt_squares_013","any",2,"reg=family|tmp=seasoned|day=10,150|mood=sad",{1,"Is that Mama's quilt?",2,"She had three squares left to go, I'm finishing 'em",1,"You can't sew a lick",2,"I know it, every stitch, I go to hold it up and ask her is this tight enough"}},
{"s9_c01_porta_john_014","any",2,"reg=civilian|mood=funny",{1,"Word of advice - don't ever hide from them in a porta-john",2,"This from experience?",1,"Two hours at the Fallas Lake campground, they couldn't get in, I couldn't get out - nobody won",2,"You're still wearing that shirt, aren't you?",1,"It's my only shirt"}},
{"s9_c01_crooked_bangs_015","any",2,"reg=family|tmp=fresh,seasoned|mood=sad",{1,"What's that you keep folded up in your shoe?",2,"Page out of the Rosewood Baptist church directory - our family - Carly sneezed right when the man took it",1,"She's all blurry",2,"She begged me to pay the seven dollars for a retake - I told her next year",2,"Look at her, nose all scrunched up"}},
{"s9_c01_library_nickel_016","any",2,"reg=civilian|tmp=fresh,seasoned|day=4,120|mood=funny",{1,"Got a library book due back in Brandenburg on the twelfth - first overdue book of my whole life",2,"I reckon they'll waive the fine",1,"I'm keeping track anyway, nickel a day - I'll owe the county about three dollars by Christmas",2,"And you'll pay it",1,"I'll pay it, somebody better be there to take it"}},
{"s9_c01_grain_bin_017","any",2,"reg=civilian|tmp=seasoned|mood=sad",{1,"How'd you ever get up on top of that grain bin?",2,"Terry boosted me, laced his fingers and said climb",1,"And Terry?",2,"I climbed"}},
{"s9_c01_plastic_deer_018","any",2,"reg=family|mood=funny",{1,"Uncle Roy put a shovel through the Grahams' plastic yard deer last night",2,"In fairness, it was dark, and it wasn't moving right",1,"It wasn't moving at all, Roy",2,"Which ain't right for a deer"}},
{"s9_c01_jiggle_radio_019","any",2,"reg=civilian|tmp=fresh|day=2,25|hour=5,10|mood=warm|world=vehicle",{1,"Who left the keys in the ignition?",2,"The lady from the Riverside lot, she was gone when I woke up",1,"She left us her car?",2,"Car, half a tank, and a note on the dash - don't wait on me, radio works if you jiggle it",1,"Did you jiggle it?",2,"Couldn't yet, just been sitting here holding the note"}},
{"s9_c01_low_board_020","any",2,"reg=family|tmp=fresh,seasoned|mood=sad|world=window",{1,"Thursday we took 'em to the pool in Muldraugh, she did cannonballs off the low board all afternoon",2,"I remember - Lifeguard kept blowing that whistle at her",1,"Her hair smelled like chlorine the whole way home - windows down - radio up",1,"That was Thursday"}},
{"s9_c01_three_hound_dogs_021","any",2,"reg=civilian|tmp=seasoned|mood=funny|world=water",{1,"Channel nineteen's got three different fellas calling themselves Hound Dog",2,"Which one had the gas?",1,"Hound Dog out of Irvington, not Hound Dog on the river - river Hound Dog's a liar",2,"And the third one?",1,"Third one just howls, I think he's having a real bad week"}},
{"s9_c01_gate_for_travis_022","any",2,"reg=family|tmp=seasoned|day=10,150|hour=19,23|mood=sad|world=road",{1,"You took the chain off the front gate again",2,"Just for the night",1,"That gate's the only thing between us and the road",2,"It's the only way Travis knows to come in, I'll sit up with the shotgun - I sit up anyhow"}},
{"s9_c01_bourbon_guard_023","any",2,"reg=civilian|mood=funny|world=door",{1,"Heard the Army put a whole platoon on the bourbon warehouses over in Bardstown",2,"Guarding bourbon",1,"While we're over here guarding a screen door with a rake",2,"First sensible thing I've heard out of the government all month"}},
{"s9_c01_lizard_on_step_024","any",2,"reg=family|tmp=fresh,seasoned|day=4,60|hour=6,11|mood=sad",{1,"Smokey left another lizard on Jamie's step",2,"Every morning since",1,"He's bringing him presents, waiting on him to come out and say good boy",2,"Don't move it, leave it where he put it"}},
{"s9_c01_glovebox_thanks_025","any",2,"reg=civilian|mood=funny",{1,"Found a flashlight in a glovebox that actually worked, said thank you out loud",2,"People do that",1,"To the glovebox",2,"People do that too, lately",1,"Then I asked it did it have any batteries it wasn't using"}},
{"s9_c02_mono_squirrel_call_001","any",1,"reg=worker|tmp=seasoned|hour=8,18|mood=sad",{1,"Used to look up at every pole I passed.. even on my day off",1,"A squirrel would crack a transformer and there went the afternoon.. one little squirrel",1,"I'd give a week's pay for a squirrel call right now"}},
{"s9_c02_mono_lawn_chairs_002","any",1,"reg=worker|sex=m|day=1,40|mood=funny",{1,"Four hundred and six thousand miles on that rig, left her on the shoulder at the Muldraugh exit",1,"Keys on the visor, like a decent person - Logbook filled out through Friday",1,"Trailer's full of lawn chairs, six hundred lawn chairs for a store in Nashville",1,"So if anybody in this county needs to sit down, I know a place"}},
{"s9_c02_mono_safety_sign_003","any",1,"reg=worker|tmp=seasoned|day=2,90|mood=funny",{1,"Sign over the time clock still says forty-one days without a lost-time accident",1,"Somebody ought to go change that, we're at zero, we've been at zero a while",1,"Guess nobody's getting the free pizza"}},
{"s9_c02_mono_county_agent_004","any",1,"reg=worker,civilian|tmp=seasoned|sex=m|day=10,120|mood=funny|world=rain",{1,"Lord, I'm not asking about the rest of it, that's between You and the Army",1,"Rain, an inch would do - half an inch, and I'll quit cussing the county extension agent",1,"Extension agent's probably dead, strike that part - just the rain"}},
{"s9_c02_mono_booth_four_005","any",1,"reg=worker|sex=f|hour=5,9|mood=sad",{1,"Coffee's on - full pot, nobody's coming, and I made the full pot anyway",1,"Booth four, you'd be Mr. Stull, eggs over hard, and send 'em back 'cause they're too hard",1,"I'd warm your cup for free the rest of my life, Mr. Stull - I'd let you send back every egg"}},
{"s9_c02_mono_slow_sign_006","any",1,"reg=worker|tmp=seasoned|mood=funny",{1,"Slow, stop - slow - stop, twenty-two years flipping this sign on 31W",1,"Nobody ever once slowed down for it, blew my hat off twice",1,"Now everybody's slow - hahaha, everybody in the county's so slow"}},
{"s9_c02_mono_thinking_of_you_007","any",1,"reg=worker|day=5,120|mood=funny",{1,"Aisle five, soup - gone, aisle six, baby stuff - gone, aisle nine, pet food, gone, and I know who ate it",1,"Aisle eleven, greeting cards - full up, not one card missing",1,"Get Well Soon, thinking of You - hahaha, a whole rack of Thinking of You"}},
{"s9_c02_mono_clementine_008","any",1,"reg=worker,family|tmp=seasoned|hour=4,7|mood=calm",{1,"Easy, Clementine, easy, I know I'm late - I know",1,"Nobody's buying the milk, I'm pouring it in the ditch, and I'm sorry about that",1,"Doesn't matter to you, though, does it? You still got to be milked - hold still, girl"}},
{"s9_c02_mono_timecard_rack_009","any",1,"reg=worker|tmp=seasoned|day=3,60|mood=grim",{1,"Timecards still in the rack by the guard shack - Friday night shift, forty-four punched in - eleven punched out",1,"I look at that rack every time I walk by - the in side",1,"Somebody should pull the cards, I'm not gonna be the somebody"}},
{"s9_c02_mono_square_crosses_010","any",1,"reg=worker|tmp=seasoned|day=5,150|mood=grim",{1,"Two-by-fours and three-inch screws, knocked out nine crosses before lunch",1,"Mr. Haddix in shop class would be proud, square, every one of 'em, I checked with the framing square",1,"Not proud of much else this week, I'm proud they're square"}},
{"s9_c02_mono_gym_floor_011","any",1,"reg=worker|tmp=seasoned|mood=funny",{1,"Waxed that gym floor every July for sixteen years - three coats, nobody on it for a week after",1,"Now there's a whole crowd of 'em shuffling around in there - half of 'em in socks",1,"Leaving marks, every last one of 'em leaving marks on my floor"}},
}
